import{_ as o,l as n,o as l,c as s,v as p,p as d,x as t,d as r,i as h,S as m,b as e}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"模型生长与深度扩展","description":"","frontmatter":{"title":"模型生长与深度扩展","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/model-growth-depth-upscaling.md","filePath":"llm/model-growth-depth-upscaling.md","lastUpdated":1789023840000}'),E={name:"llm/model-growth-depth-upscaling.md"};function c(B,a,u,f,A,g){const i=n("Mermaid");return l(),s("div",null,[a[1]||(a[1]=p('<h1 id="模型生长与深度扩展" tabindex="-1">模型生长与深度扩展 <a class="header-anchor" href="#模型生长与深度扩展" aria-label="Permalink to &quot;模型生长与深度扩展&quot;">​</a></h1><div class="epigraph"><p>把已训好的浅网复制、插层或叠成更深的初始化，比从随机深网再走一遍压熵段更省；但插入的恒等必须在数值上真是恒等。</p><footer>—— Gong et al., Efficient Training of BERT by Progressively Stacking, ICLR 2019；Chen et al., bert2BERT, ACL 2022；Kim et al., SOLAR 10.7B 的 depth up-scaling, 2023</footer></div><p><a href="/llm/proxy-model-experiments">上一课</a>要求形状改动先在代理上做应力测试。缺口是：目标不是从零加 \\(L\\)，而是已有检查点要<strong>长深</strong>。Gong 等人逐步 stacking BERT；Chen 等人的 bert2BERT 把小模型映射到大模型初始化；SOLAR 把层复制插进中段做 depth up-scaling。本课写生长的数值条件，接 <a href="/llm/depth-scaled-init">深度缩放</a> 与残差恒等，不把生长写成免费的 \\(N\\) 倍增。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>随机初始化一个更深的模型，压熵段要重买。生长希望：\\(x\\leftarrow x+F_{\\mathrm{new}}(x)\\) 在起步时 \\(F_{\\mathrm{new}}\\approx 0\\)，旧层功能保留。实现手段：复制已有层、或插入 LayerScale \\(\\alpha=0\\) 的新层、或把相邻层插值成新层。失败模式：复制层的残差增量立刻翻倍（同一 \\(F\\) 加两次），总线 RMS 跳变，注意力熵塌缩——稳定性单元的传感器会在生长后第一步报警。</p><p>宽度扩展（bert2BERT 一类）还要扩 \\(d\\)：矩阵要补行补列。补零保持函数恒等；补随机则破坏。μP 下扩宽应按 infshape 的方差补，而不是 Xavier 再来一遍不管旧权重。</p><p><span class="marginnote">复制层会复制注意力头的功能，也可能复制已经塌缩的头。生长不是治熵塌缩的药；先在源模型上把传感器调健康，再复制。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>深度扩展常见配方：</p><ol><li>选插入点（常在中后段，保留底浅层与顶层 LN/头）。</li><li>新层初始化为恒等：\\(\\alpha=0\\)，或输出投影乘 0，或 DeepNorm 系数按新 \\(L\\) 重算。</li><li>短 warmup / 小 \\(\\eta\\) 先训新层或全体，再回到原日程。</li><li>代理上做：生长后 100 step 的总线 RMS、熵、LSE 相对生长前连续，不允许跳一个数量级。</li></ol><p>SOLAR 式把层块复制再继续预训练，本质是用数据把「双份 \\(F\\)」重新正交化。预算仍要计入：生长后 \\(N\\) 变了，\\(D\\) 应按新的推理/训练最优重估，不能认为「已经训过浅的，深的白送」。</p><p>宽度扩展：对 \\(W\\) 做切块复制或填零，嵌入补行要与词表课一致。tied 头与嵌入必须同步扩。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>恒等初始化使旧映射在函数空间连续。优化器状态 \\(m,v\\) 对新增参数是 0，冷坐标碰上 <a href="/llm/adam-epsilon-update-scale">ε 课</a> 的巨步——新层应更大 \\(\\varepsilon\\) 或更小 \\(\\eta\\)，与嵌入分组同类。复制已有层若连 \\(v\\) 一起复制，等于假设新层梯度统计相同，通常过猛；更稳是只复制权重、优化器状态清零，再用短 warmup。</p><p>Stacking 把浅网学到的回路重复两遍，可能加速深度方向的组合，也可能让模型满足于重复同一局部算法。后续训练必须有足够 \\(D\\) 把重复回路拆开。否则只是更贵的浅网。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不覆盖把 CNN 长成 Transformer。下一课的稠密→MoE 是另一类生长：复制 FFN 成专家，而不是插层。合并课则把<strong>已有多个模型</strong>合成，不增加深度。生长是单轨迹变形状；合并是多轨迹变一点。</p>',17)),(l(),d(m,null,{default:t(()=>[h(i,{id:"mermaid-68",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E5%B7%B2%E8%AE%AD%E6%B5%85%E6%A3%80%E6%9F%A5%E7%82%B9%22%5D%20--%3E%20ID%5B%22%E6%96%B0%E5%B1%82%E6%81%92%E7%AD%89%E5%88%9D%E5%A7%8B%E5%8C%96%22%5D%0A%20%20ID%20--%3E%20WU%5B%22%E7%9F%AD%20warmup%20%2F%20%E6%96%B0%E5%B1%82%E5%B0%8F%E7%BB%84%20eta%22%5D%0A%20%20WU%20--%3E%20SEN%5B%22%E4%BC%A0%E6%84%9F%E5%99%A8%E4%B8%8D%E8%B7%B3%E5%8F%98%22%5D%0A%20%20SEN%20--%3E%20PRE%5B%22%E7%BB%A7%E7%BB%AD%E9%A2%84%E8%AE%AD%E7%BB%83%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("h2",{id:"小结",tabindex:"-1"},[r("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[3]||(a[3]=e("ul",null,[e("li",null,"深度扩展靠插入函数恒等的层，避免双份 \\(F\\) 把总线打飞。"),e("li",null,"新参数是冷坐标，优化器状态与 \\(\\varepsilon\\) 要分组；先在代理上查传感器连续性。"),e("li",null,"生长后 \\(N\\) 变了，数据预算要重估；复制前先治源模型的熵塌缩。"),e("li",null,"只复制权重、清零 \\(m,v\\)，通常比连状态一起复制更稳。"),e("li",null,"出处：Gong et al., ICLR 2019；Chen et al., ACL 2022；Kim et al., SOLAR, 2023。")],-1))])}const _=o(E,[["render",c]]);export{S as __pageData,_ as default};
